import sys

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    N, M, K = map(int, data)
    MOD = 998244353
    dp = [0] * (K + 1)
    dp[0] = 1
    for _ in range(N):
        ndp = [0] * (K + 1)
        for s in range(K + 1):
            if dp[s] == 0:
                continue
            for x in range(1, M + 1):
                if s + x <= K:
                    ndp[s + x] = (ndp[s + x] + dp[s]) % MOD
        dp = ndp
    ans = sum(dp[s] for s in range(N, K + 1)) % MOD
    print(ans)

if __name__ == '__main__':
    main()

