#include <iostream>
#include <queue>
using namespace std;
int main() {
    int K;
    if (!(cin >> K)) return 0;
    queue<long long> q;
    for (int i = 1; i <= 9; ++i) q.push(i);
    long long ans = 0;
    for (int cnt = 0; cnt < K; ) {
        long long x = q.front(); q.pop();
        ++cnt;
        if (cnt == K) { ans = x; break; }
        int d = x % 10;
        for (int nd = d - 1; nd <= d + 1; ++nd) {
            if (nd >= 0 && nd <= 9) q.push(x * 10 + nd);
        }
    }
    cout << ans << endl;
    return 0;
}

