import sys
from collections import Counter

def solve():
    data = sys.stdin.read().split()
    if not data:
        return
    N = int(data[0])
    K = int(data[1])
    S = data[2]
    cnt = Counter(S)
    chars = list(cnt.keys())
    freq = {c: cnt[c] for c in chars}
    total = 0

    def backtrack(cur):
        nonlocal total
        if len(cur) == N:
            ok = True
            for i in range(N - K + 1):
                sub = cur[i:i+K]
                if sub == sub[::-1]:
                    ok = False
                    break
            if ok:
                total += 1
            return
        for c in chars:
            if freq[c] > 0:
                freq[c] -= 1
                cur.append(c)
                backtrack(cur)
                cur.pop()
                freq[c] += 1

    backtrack([])
    print(total)

if __name__ == '__main__':
    solve()

