#include <bits/stdc++.h>
using namespace std;
int main() {
    int N, M;
    cin >> N >> M;
    vector<pair<int,int>> moves;
    for (int dx = 0; dx*dx <= M; ++dx) {
        int rem = M - dx*dx;
        int dy = (int)sqrt(rem);
        if (dy*dy == rem) {
            if (dx == 0 && dy == 0) continue;
            if (dx == 0) {
                moves.push_back({0, dy});
                moves.push_back({0, -dy});
            } else if (dy == 0) {
                moves.push_back({dx, 0});
                moves.push_back({-dx, 0});
            } else {
                moves.push_back({dx, dy});
                moves.push_back({dx, -dy});
                moves.push_back({-dx, dy});
                moves.push_back({-dx, -dy});
            }
        }
    }
    vector<vector<int>> dist(N, vector<int>(N, -1));
    queue<pair<int,int>> q;
    dist[0][0] = 0;
    q.push({0,0});
    while (!q.empty()) {
        int x = q.front().first, y = q.front().second;
        q.pop();
        for (auto& m : moves) {
            int dx = m.first, dy = m.second;
            int nx = x + dx, ny = y + dy;
            if (nx >= 0 && nx < N && ny >= 0 && ny < N && dist[nx][ny] == -1) {
                dist[nx][ny] = dist[x][y] + 1;
                q.push({nx, ny});
            }
        }
    }
    for (int i = 0; i < N; ++i) {
        for (int j = 0; j < N; ++j) {
            if (j) cout << ' ';
            cout << dist[i][j];
        }
        cout << '\n';
    }
    return 0;
}

