import math
import sys

def main():
    D = int(sys.stdin.readline().strip())
    ans = D  # 初始最大可能差（x=0,y=0）
    limit = int(math.isqrt(D)) + 1
    for x in range(limit + 1):
        x2 = x * x
        rem = D - x2
        if rem >= 0:
            y = int(math.isqrt(rem))
            # 检查 y 和 y+1
            for yy in (y, y + 1):
                diff = abs(x2 + yy * yy - D)
                if diff < ans:
                    ans = diff
        else:
            # x^2 > D，y=0 最优
            diff = abs(x2 - D)
            if diff < ans:
                ans = diff
    print(ans)

if __name__ == '__main__':
    main()

