import sys

def main():
    data = sys.stdin.read().split()
    if not data:
        return
    N = int(data[0]); M = int(data[1])
    parent = list(range(N+1))
    size = [1]*(N+1)
    edges = [0]*(N+1)
    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x
    idx = 2
    for _ in range(M):
        u = int(data[idx]); v = int(data[idx+1]); idx += 2
        ru = find(u); rv = find(v)
        if ru == rv:
            edges[ru] += 1
        else:
            parent[rv] = ru
            size[ru] += size[rv]
            edges[ru] += edges[rv] + 1
    for i in range(1, N+1):
        if parent[i] == i:
            if size[i] != edges[i]:
                print("No")
                return
    print("Yes")

if __name__ == "__main__":
    main()

