int main() {
    string S;
    cin >> S;
    vector<vector<char>> st;
    bool in_box[26] = {false};
    for (char c : S) {
        if (c == '(') {
            st.push_back({});
        } else if (c == ')') {
            if (!st.empty()) {
                for (char ch : st.back()) in_box[ch - 'a'] = false;
                st.pop_back();
            }
        } else {
            int idx = c - 'a';
            if (in_box[idx]) {
                cout << "No" << endl;
                return 0;
            }
            in_box[idx] = true;
            if (!st.empty()) st.back().push_back(c);
        }
    }
    cout << "Yes" << endl;
    return 0;
}

