#include <algorithm>
using namespace std;
typedef long long ll;
int main(){
    int N,K,D;
    cin>>N>>K>>D;
    vector<ll> a(N);
    for(int i=0;i<N;i++) cin>>a[i];
    vector<vector<vector<ll>>> dp(N+1, vector<vector<ll>>(K+1, vector<ll>(D, -1)));
    dp[0][0][0]=0;
    for(int i=1;i<=N;i++){
        ll val=a[i-1];
        int mod=((val%D)+D)%D;
        for(int j=0;j<=K;j++){
            for(int r=0;r<D;r++){
                dp[i][j][r]=dp[i-1][j][r];
                if(j>0){
                    int prev=((r-mod)%D+D)%D;
                    if(dp[i-1][j-1][prev]!=-1){
                        ll cand=dp[i-1][j-1][prev]+val;
                        if(cand>dp[i][j][r]) dp[i][j][r]=cand;
                    }
                }
            }
        }
    }
    ll ans=dp[N][K][0];
    if(ans<0) cout<<-1<<endl;
    else cout<<ans<<endl;
    return 0;
}

