int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int N;
    if (!(cin >> N)) return 0;
    vector<string> S(N), T(N);
    unordered_map<string, int> id;
    int cnt = 0;
    for (int i = 0; i < N; ++i) {
        cin >> S[i] >> T[i];
        if (!id.count(S[i])) id[S[i]] = cnt++;
        if (!id.count(T[i])) id[T[i]] = cnt++;
    }
    vector<int> out(cnt, -1);
    vector<int> indeg(cnt, 0);
    for (int i = 0; i < N; ++i) {
        int u = id[S[i]], v = id[T[i]];
        out[u] = v;
        indeg[v]++;
    }
    queue<int> q;
    for (int i = 0; i < cnt; ++i) if (indeg[i] == 0) q.push(i);
    int processed = 0;
    while (!q.empty()) {
        int u = q.front(); q.pop();
        if (out[u] != -1) {
            int v = out[u];
            indeg[v]--;
            if (indeg[v] == 0) q.push(v);
            processed++;
        }
    }
    if (processed == N) cout << "Yes\n";
    else cout << "No\n";
    return 0;
}

