def main():
    data = sys.stdin.read().strip()
    if not data:
        return
    N = int(data)
    MAXQ = 1000000
    is_prime = [True] * (MAXQ + 1)
    is_prime[0] = is_prime[1] = False
    for i in range(2, int(MAXQ ** 0.5) + 1):
        if is_prime[i]:
            step = i
            start = i * i
            for j in range(start, MAXQ + 1, step):
                is_prime[j] = False
    primes = [i for i, v in enumerate(is_prime) if v]
    ans = 0
    for q in primes:
        if q == 2:
            continue
        q3 = q * q * q
        if q3 > N:
            break
        limit = N // q3
        max_p = q - 1
        if limit < max_p:
            max_p = limit
