#include <queue>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int N, M, K;
    cin >> N >> M >> K;
    vector<vector<int>> adj(N+1);
    for (int i = 0; i < M; ++i) {
        int a, b; cin >> a >> b;
        adj[a].push_back(b);
        adj[b].push_back(a);
    }
    vector<int> max_rem(N+1, -1);
    priority_queue<pair<int,int>> pq; // max-heap by rem
    for (int i = 0; i < K; ++i) {
        int p, h; cin >> p >> h;
        if (h > max_rem[p]) {
            max_rem[p] = h;
            pq.push({h, p});
        }
    }
    while (!pq.empty()) {
        auto [rem, u] = pq.top(); pq.pop();
        if (rem < max_rem[u]) continue;
        for (int v : adj[u]) {
            int nrem = rem - 1;
            if (nrem > max_rem[v]) {
                max_rem[v] = nrem;
                pq.push({nrem, v});
            }
        }
    }
    vector<int> ans;
    for (int v = 1; v <= N; ++v) if (max_rem[v] >= 0) ans.push_back(v);
    cout << ans.size() << "\n";
    for (size_t i = 0; i < ans.size(); ++i) {
        cout << ans[i] << (i+1 == ans.size() ? "" : " ");
    }
    cout << "\n";
    return 0;
}

