import sys
def main():
    data = sys.stdin.read().strip().split()
    if not data: return
    it = iter(data)
    N = int(next(it)); T = int(next(it)); M = int(next(it))
    bad = [[False]*(N+1) for _ in range(N+1)]
    for _ in range(M):
        a = int(next(it)); b = int(next(it))
        bad[a][b] = bad[b][a] = True
    belong = [-1]*(N+1)
    ans = 0
    def dfs(player, cur):
        nonlocal ans
        if player == N+1:
            if cur == T:
                ans += 1
            return
        for j in range(cur):
            ok = True
            for p in range(1, player):
                if belong[p] == j and bad[player][p]:
                    ok = False
                    break
            if ok:
                belong[player] = j
                dfs(player+1, cur)
                belong[player] = -1
        if cur < T:
            belong[player] = cur
            dfs(player+1, cur+1)
            belong[player] = -1
    dfs(1, 0)
    print(ans)
if __name__ == '__main__':
    main()

