#include <string>
using namespace std;

int lcp(const string& a, const string& b) {
    int n = min(a.size(), b.size());
    int c = 0;
    while (c < n && a[c] == b[c]) ++c;
    return c;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int N;
    if (!(cin >> N)) return 0;
    vector<pair<string, int>> v(N);
    for (int i = 0; i < N; ++i) {
        cin >> v[i].first;
        v[i].second = i;
    }
    sort(v.begin(), v.end());
    vector<int> lcp_arr(N - 1);
    for (int i = 0; i < N - 1; ++i) {
        lcp_arr[i] = lcp(v[i].first, v[i+1].first);
    }
    vector<int> ans(N, 0);
    for (int i = 0; i < N; ++i) {
        int mx = 0;
        if (i > 0) mx = max(mx, lcp_arr[i-1]);
        if (i < N - 1) mx = max(mx, lcp_arr[i]);
        ans[v[i].second] = mx;
    }
    for (int i = 0; i < N; ++i) {
        cout << ans[i] << '\n';
    }
    return 0;
}

