import sys
from collections import deque

def main():
    data = sys.stdin.read().strip().split()
    if not data: return
    it = iter(data)
    N = int(next(it))
    x,y,P = [],[],[]
    for _ in range(N):
        x.append(int(next(it))); y.append(int(next(it))); P.append(int(next(it)))
    def check(S):
        adj = [[] for _ in range(N)]
        for i in range(N):
            for j in range(N):
                if i!=j and P[i]*S >= abs(x[i]-x[j])+abs(y[i]-y[j]):
                    adj[i].append(j)
        for r in range(N):
            vis = [False]*N
            q = deque([r]); vis[r]=True
            while q:
                u=q.popleft()
                for v in adj[u]:
                    if not vis[v]:
                        vis[v]=True; q.append(v)
            if all(vis): return True
        return False
    maxd = 0; minP = min(P)
    for i in range(N):
        for j in range(N):
            d = abs(x[i]-x[j])+abs(y[i]-y[j])
            if d>maxd: maxd=d
    lo, hi = 0, maxd//minP + 2
    while lo < hi:
        mid = (lo+hi)//2
        if check(mid): hi = mid
        else: lo = mid+1
    print(lo)

if __name__ == '__main__':
    main()

