    vector<double> best(N+1, 0.0);
    double ans = -1e18;
    for (int i=1; i<=N; ++i) {
        for (int j=i; j>=1; --j) {
            double val = P[i] + (j==1 ? 0.0 : 0.9 * best[j-1]);
            best[j] = max(best[j], val);
            double denom = 10.0 * (1.0 - pow(0.9, j));
            double r = val / denom - 1200.0 / sqrt((double)j);
            ans = max(ans, r);
        }
    }
    cout << fixed << setprecision(15) << ans << endl;
    return 0;
}

