    long long small_sum = 0;
    for (int i=0; i<M; ++i) {
        if ((int)small.size() < K) {
            small.insert(A[i]);
            small_sum += A[i];
        } else {
            large.insert(A[i]);
        }
    }
    while ((int)small.size() < K && !large.empty()) {
        auto it = large.begin();
        small.insert(*it); small_sum += *it; large.erase(it);
    }
    while ((int)small.size() > K) {
        auto it = small.end(); --it;
        large.insert(*it); small_sum -= *it; small.erase(it);
    }
    vector<long long> ans;
    ans.push_back(small_sum);
