int main() {
    int N, M;
    cin >> N >> M;
    vector<vector<int>> adj(N+1);
    for (int i=0; i<M; i++) {
        int u, v; cin >> u >> v;
        adj[u].push_back(v);
    }
    long long reach = 0;
    for (int i=1; i<=N; i++) {
        vector<bool> vis(N+1, false);
        queue<int> q;
        q.push(i);
        vis[i] = true;
        while (!q.empty()) {
            int u = q.front(); q.pop();
            for (int v : adj[u]) {
                if (!vis[v]) {
                    vis[v] = true;
                    reach++;
                    q.push(v);
                }
            }
        }
    }
    cout << reach - M << endl;
    return 0;
}

