                if(i==H||j==W) dp[i][j]=1;
                else dp[i][j]=min({dp[i+1][j], dp[i][j+1], dp[i+1][j+1]})+1;
                ans+=dp[i][j];
            }
        }
    }
    cout<<ans<<endl;
    return 0;
}

