#include <iostream>
#include <vector>
#include <unordered_set>
using namespace std;

struct DSU {
    vector<int> p;
    DSU(int n): p(n+1) { for(int i=1;i<=n;++i) p[i]=i; }
    int find(int x) { return p[x]==x ? x : p[x]=find(p[x]); }
    void unite(int x, int y) { x=find(x); y=find(y); if(x!=y) p[x]=y; }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int N, M; cin >> N >> M;
    DSU dsu(N);
    for(int i=0;i<M;++i) {
        int u,v; cin >> u >> v;
        if(u!=v) dsu.unite(u,v);
    }
    int K; cin >> K;
    unordered_set<unsigned long long> forbidden;
    for(int i=0;i<K;++i) {
        int x,y; cin >> x >> y;
        int cx = dsu.find(x), cy = dsu.find(y);
        if(cx > cy) swap(cx, cy);
        forbidden.insert(((unsigned long long)cx << 32) | cy);
    }
    int Q; cin >> Q;
    while(Q--) {
        int p,q; cin >> p >> q;
        int cp = dsu.find(p), cq = dsu.find(q);
        if(cp == cq) {
            cout << "Yes\n";
        } else {
            if(cp > cq) swap(cp, cq);
            if(forbidden.count(((unsigned long long)cp << 32) | cq)) cout << "No\n";
            else cout << "Yes\n";
        }
    }
    return 0;
}

