import sys
from collections import deque

def main():
    input = sys.stdin.read
    data = input().split()
    if not data: return
    N = int(data[0])
    adj = [[] for _ in range(N+1)]
    deg = [0]*(N+1)
    idx=1
    for _ in range(N-1):
        u=int(data[idx]); v=int(data[idx+1]); idx+=2
        adj[u].append(v); adj[v].append(u)
        deg[u]+=1; deg[v]+=1
    is_center = [True]*(N+1)
    cur = deg[:]
    for i in range(1,N+1):
        if deg[i]==1:
            is_center[i]=False
    q = deque()
    for i in range(1,N+1):
        if cur[i]==2:
            q.append(i)
    while q:
        u = q.popleft()
        if cur[u]!=2 or not is_center[u]:
            continue
        v = -1
        for w in adj[u]:
            if cur[w]==2 and is_center[w]:
                v = w; break
        if v==-1:
            continue
        is_center[u]=False; is_center[v]=False
        for w in adj[u]:
            if w!=v:
                cur[w]-=1
                if cur[w]==2 and is_center[w]: q.append(w)
        for w in adj[v]:
            if w!=u:
                cur[w]-=1
                if cur[w]==2 and is_center[w]: q.append(w)
    res = [deg[i] for i in range(1,N+1) if is_center[i]]
    res.sort()
    print(' '.join(map(str,res)))

if __name__=='__main__':
    main()

