#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;
using ll = long long;

ll pow_mod(ll x, ll y, ll m) {
    ll res = 1 % m;
    x %= m;
    while (y > 0) {
        if (y & 1) res = (res * x) % m;
        x = (x * x) % m;
        y >>= 1;
    }
    return res;
}

ll w(ll x, ll y, ll m) {
    return (pow_mod(x, y, m) + pow_mod(y, x, m)) % m;
}

int main() {
    int N;
    ll M;
    cin >> N >> M;
    vector<ll> A(N);
    for (int i = 0; i < N; ++i) cin >> A[i];
    vector<vector<ll>> weight(N, vector<ll>(N));
    for (int i = 0; i < N; ++i)
        for (int j = 0; j < N; ++j)
            if (i != j) weight[i][j] = w(A[i], A[j], M);
    vector<bool> inTree(N, false);
    vector<ll> dist(N, 0);
    inTree[0] = true;
    for (int i = 1; i < N; ++i) dist[i] = weight[0][i];
    ll ans = 0;
    for (int iter = 1; iter < N; ++iter) {
        int u = -1;
        for (int i = 0; i < N; ++i)
            if (!inTree[i] && (u == -1 || dist[i] > dist[u]))
                u = i;
        inTree[u] = true;
        ans += dist[u];
        for (int i = 0; i < N; ++i)
            if (!inTree[i])
                dist[i] = max(dist[i], weight[u][i]);
    }
    cout << ans << endl;
    return 0;
}

