import sys

def solve():
    input = sys.stdin.read
    data = input().split()
    if not data: return
    H = int(data[0]); W = int(data[1])
    A = [list(map(int, data[2+i*W:2+(i+1)*W])) for i in range(H)]
    horiz = [[False]*W for _ in range(H)]
    for i in range(H):
        for j in range(W):
            ok = False
            if j>0 and A[i][j]==A[i][j-1]: ok=True
            if j<W-1 and A[i][j]==A[i][j+1]: ok=True
            horiz[i][j]=ok
    c = [[0]*W for _ in range(H-1)]
    for i in range(H-1):
        for j in range(W):
            c[i][j] = A[i][j] ^ A[i+1][j]
    INF = 10**9
    dp = [[INF,INF],[INF,INF]]
    for x0 in (0,1):
        for x1 in (0,1):
            d1 = x0 ^ x1
            ok = True
            for j in range(W):
                if not horiz[0][j]:
                    if d1 != c[0][j]:
                        ok=False; break
            if ok:
                dp[x0][x1] = x0 + x1
    for i in range(1, H-1):
        ndp = [[INF,INF],[INF,INF]]
        for xp in (0,1):
            for xc in (0,1):
                if dp[xp][xc]==INF: continue
                d_prev = xp ^ xc
                for xn in (0,1):
                    d_cur = xc ^ xn
                    ok = True
                    forced = -1
                    for j in range(W):
                        if not horiz[i][j]:
                            if d_prev != c[i-1][j]:
                                if forced == -1:
                                    forced = c[i][j]
                                elif forced != c[i][j]:
                                    ok=False; break
                    if not ok: continue
                    if forced != -1 and d_cur != forced: continue
                    cost = dp[xp][xc] + xn
                    if cost < ndp[xc][xn]:
                        ndp[xc][xn] = cost
        dp = ndp
    ans = INF
    for xp in (0,1):
        for xc in (0,1):
            if dp[xp][xc]==INF: continue
            d_prev = xp ^ xc
            ok = True
            for j in range(W):
                if not horiz[H-1][j]:
                    if d_prev != c[H-2][j]:
                        ok=False; break
            if ok:
                ans = min(ans, dp[xp][xc])
    print(-1 if ans==INF else ans)

if __name__ == '__main__':
    solve()

