#include <iostream>
#include <vector>
#include <queue>
#include <unordered_set>
#include <algorithm>
using namespace std;
int main() {
    int N, K;
    if (!(cin >> N >> K)) return 0;
    vector<long long> A(N);
    for (int i = 0; i < N; ++i) cin >> A[i];
    sort(A.begin(), A.end());
    A.erase(unique(A.begin(), A.end()), A.end());
    N = A.size();
    priority_queue<long long, vector<long long>, greater<long long>> pq;
    unordered_set<long long> seen;
    for (int i = 0; i < N; ++i) {
        if (seen.insert(A[i]).second) pq.push(A[i]);
    }
    long long ans = 0;
    for (int i = 0; i < K; ++i) {
        ans = pq.top(); pq.pop();
        for (int j = 0; j < N; ++j) {
            long long nxt = ans + A[j];
            if (seen.find(nxt) == seen.end()) {
                seen.insert(nxt); pq.push(nxt);
            }
        }
    }
    cout << ans << endl;
    return 0;
}

