using namespace std;
int main() {
    ios::sync_with_stdio(false); cin.tie(nullptr);
    int N; cin >> N;
    vector<vector<int>> pre(N+1);
    vector<vector<int>> rev(N+1);
    for (int i=1; i<=N; ++i) {
        int c; cin >> c;
        pre[i].resize(c);
        for (int j=0; j<c; ++j) {
            cin >> pre[i][j];
            rev[pre[i][j]].push_back(i);
        }
    }
    vector<bool> inS(N+1, false);
    queue<int> q; q.push(1); inS[1]=true;
    while (!q.empty()) {
        int u = q.front(); q.pop();
        for (int v : pre[u]) if (!inS[v]) { inS[v]=true; q.push(v); }
    }
    vector<int> indeg(N+1, 0);
    for (int i=1; i<=N; ++i) if (inS[i] && i!=1) indeg[i] = pre[i].size();
    queue<int> q2;
    for (int i=1; i<=N; ++i) if (inS[i] && i!=1 && indeg[i]==0) q2.push(i);
    vector<int> ans;
    while (!q2.empty()) {
        int u = q2.front(); q2.pop();
        ans.push_back(u);
