#include <iostream>
#include <vector>
#include <queue>
#include <string>
#include <algorithm>

using namespace std;

const int INF = 1e9;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int H, W, T;
    if (!(cin >> H >> W >> T)) return 0;
    vector<string> grid(H);
    for (int i = 0; i < H; i++) cin >> grid[i];

    vector<pair<int,int>> pts;
    int S = -1, G = -1;
    for (int i = 0; i < H; i++) {
        for (int j = 0; j < W; j++) {
            if (grid[i][j] == 'S') { S = pts.size(); pts.push_back({i,j}); }
            else if (grid[i][j] == 'G') { G = pts.size(); pts.push_back({i,j}); }
            else if (grid[i][j] == 'o') { pts.push_back({i,j}); }
        }
    }
    int N = pts.size();
    int n = N - 2;
    vector<vector<int>> dist(N, vector<int>(N, INF));
    int dr[] = {1, -1, 0, 0};
    int dc[] = {0, 0, 1, -1};
    for (int s = 0; s < N; s++) {
        vector<vector<int>> d(H, vector<int>(W, INF));
        queue<pair<int,int>> q;
        int sr = pts[s].first, sc = pts[s].second;
        d[sr][sc] = 0;
        q.push({sr, sc});
        while (!q.empty()) {
            int r = q.front().first, c = q.front().second; q.pop();
            for (int dir = 0; dir < 4; dir++) {
                int nr = r + dr[dir], nc = c + dc[dir];
                if (nr < 0 || nr >= H || nc < 0 || nc >= W) continue;
                if (grid[nr][nc] == '#') continue;
                if (d[nr][nc] > d[r][c] + 1) {
                    d[nr][nc] = d[r][c] + 1;
                    q.push({nr, nc});
                }
            }
        }
        for (int t = 0; t < N; t++) {
            dist[s][t] = d[pts[t].first][pts[t].second];
        }
    }

    if (dist[S][G] > T) {
        cout << -1 << endl;
        return 0;
    }

    int fullmask = 1 << n;
    vector<vector<int>> dp(fullmask, vector<int>(n + 1, INF));
    dp[0][0] = 0;
    int ans = 0;
    for (int mask = 0; mask < fullmask; mask++) {
        for (int i = 0; i <= n; i++) {
            if (dp[mask][i] == INF) continue;
            int cur = (i == 0) ? S : i + 1;
            if (dp[mask][i] + dist[cur][G] <= T) {
                int cnt = __builtin_popcount(mask);
                if (cnt > ans) ans = cnt;
            }
            for (int j = 1; j <= n; j++) {
                if (mask & (1 << (j - 1))) continue;
                int nxt = j + 1;
                if (dist[cur][nxt] == INF) continue;
                int nmask = mask | (1 << (j - 1));
                if (dp[mask][i] + dist[cur][nxt] < dp[nmask][j]) {
                    dp[nmask][j] = dp[mask][i] + dist[cur][nxt];
                }
            }
        }
    }
    cout << ans << endl;
    return 0;
}

