#include <iostream>
using namespace std;
using ll = long long;

ll count_nodes(ll u, ll r, ll N) {
    if (u > N) return 0;
    if (r == 0) return 1;
    __int128 left = (__int128)u << r;
    if (left > N) return 0;
    __int128 right = left + ((__int128)1 << r) - 1;
    if (right > N) right = N;
    return (ll)(right - left + 1);
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    ll T; cin >> T;
    while (T--) {
        ll N, X, K; cin >> N >> X >> K;
        ll ans = 0;
        for (ll d = 0; d <= K; d++) {
            ll a = X >> d;
            if (a == 0) break;
            ll rem = K - d;
            if (rem == 0) {
                ans++;
            } else {
                ans += count_nodes(a, rem, N);
                if (d > 0) {
                    ll child = X >> (d - 1);
                    ans -= count_nodes(child, rem - 1, N);
                }
            }
        }
        cout << ans << '\n';
    }
    return 0;
}

