import sys
from collections import deque

def main():
    input = sys.stdin.readline
    N = int(input())
    A = list(map(int, input().split()))
    S = [input().strip() for _ in range(N)]
    adj = [[] for _ in range(N)]
    for i in range(N):
        for j in range(N):
            if S[i][j] == 'Y':
                adj[i].append(j)
    INF = 10**18
    dist = [[INF]*N for _ in range(N)]
    best = [[0]*N for _ in range(N)]
    for s in range(N):
        dist[s][s] = 0
        best[s][s] = A[s]
        q = deque([s])
        while q:
            u = q.popleft()
            d = dist[s][u]
            val = best[s][u]
            for v in adj[u]:
                if dist[s][v] == INF:
                    dist[s][v] = d + 1
                    best[s][v] = val + A[v]
                    q.append(v)
                elif dist[s][v] == d + 1:
                    if val + A[v] > best[s][v]:
                        best[s][v] = val + A[v]
    Q = int(input())
    out = []
    for _ in range(Q):
        u, v = map(int, input().split())
        u -= 1; v -= 1
        if dist[u][v] == INF:
            out.append('Impossible')
        else:
            out.append(f'{dist[u][v]} {best[u][v]}')
    print('\n'.join(out))

if __name__ == '__main__':
    main()

