using namespace std;
typedef long long ll;
const ll INF = 1e18;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int N, M;
    cin >> N >> M;
    vector<ll> A(N+1), C(N+1);
    for (int i=1; i<=N; ++i) cin >> A[i];
    for (int i=1; i<=N; ++i) cin >> C[i];
    vector<bool> need(N+1, false);
    for (int i=0; i<M; ++i) {
        int x; cin >> x; need[x] = true;
    }
    vector<ll> dp(N+1, INF);
    dp[0] = 0;
    for (int i=1; i<=N; ++i) {
        vector<ll> nxt(N+1, INF);
        ll mn = C[i];
        for (int k=0; k<i; ++k) {
            if (dp[k] < INF) {
                nxt[k+1] = min(nxt[k+1], dp[k] + A[i] + mn);
            }
            mn = min(mn, C[i - k - 1]);
        }
        if (dp[i] < INF) {
            nxt[i+1] = min(nxt[i+1], dp[i] + A[i] + mn);
        }
        if (!need[i]) {
            for (int k=0; k<=i; ++k) {
                if (dp[k] < INF) nxt[k] = min(nxt[k], dp[k]);
            }
        }
        dp = move(nxt);
    }
    ll ans = INF;
    for (int k=0; k<=N; ++k) if (dp[k] < INF) ans = min(ans, dp[k]);
    cout << ans << "\n";
    return 0;
}

