int main() {
    int N, M; if (!(cin >> N >> M)) return 0;
    vector<vector<int>> adj(N+1);
    for (int i=0; i<M; i++) { int u,v; cin>>u>>v; adj[u].push_back(v); adj[v].push_back(u); }
    int K; cin >> K;
    vector<int> p(K), d(K);
    for (int i=0; i<K; i++) cin >> p[i] >> d[i];
    vector<vector<int>> dist(K, vector<int>(N+1, -1));
    for (int i=0; i<K; i++) {
        queue<int> q; q.push(p[i]); dist[i][p[i]]=0;
        while(!q.empty()){ int u=q.front(); q.pop(); for(int v:adj[u]) if(dist[i][v]==-1){ dist[i][v]=dist[i][u]+1; q.push(v); } }
    }
    vector<bool> forbidden(N+1, false);
    bool ok = true;
    for (int i=0; i<K; i++) for (int v=1; v<=N; v++) if (dist[i][v]!=-1 && dist[i][v] < d[i]) forbidden[v]=true;
    for (int i=0; i<K; i++) if (d[i]==0 && forbidden[p[i]]) ok=false;
    for (int i=0; i<K; i++) { bool has=false; for(int v=1; v<=N; v++) if(dist[i][v]==d[i] && !forbidden[v]){has=true; break;} if(!has) ok=false; }
    vector<bool> black(N+1, false);
    if (ok) {
        for (int i=0; i<K; i++) {
            int cur=1e9; for(int v=1; v<=N; v++) if(black[v] && dist[i][v]!=-1) cur=min(cur, dist[i][v]);
            if (cur > d[i]) for(int v=1; v<=N; v++) if(dist[i][v]==d[i] && !forbidden[v] && !black[v]){ black[v]=true; break; }
        }
    }
    if (ok && count(black.begin()+1, black.end(), true)==0) black[1]=true;
    if (ok) {
        for (int i=0; i<K; i++) {
            int cur=1e9; for(int v=1; v<=N; v++) if(black[v] && dist[i][v]!=-1) cur=min(cur, dist[i][v]);
            if (cur != d[i]) { ok=false; break; }
        }
    }
    if (!ok) cout << "No\n";
    else {
        cout << "Yes\n"; string s(N,'0'); for(int i=1;i<=N;i++) if(black[i]) s[i-1]='1'; cout << s << "\n";
    }
    return 0;
}

