    if (ok) {
        for (int i=0; i<K; i++) {
            int cur=1e9; for(int v=1; v<=N; v++) if(black[v] && dist[i][v]!=-1) cur=min(cur, dist[i][v]);
            if (cur != d[i]) { ok=false; break; }
        }
