    unordered_map<int, int> freq;
    int distinct = 0;
    for (int i = 0; i < K; ++i) {
        if (freq[c[i]]++ == 0) ++distinct;
    }
    int ans = distinct;
    for (int i = K; i < N; ++i) {
        if (--freq[c[i - K]] == 0) --distinct;
        if (freq[c[i]]++ == 0) ++distinct;
        if (distinct > ans) ans = distinct;
    }
    cout << ans << endl;
    return 0;
}

