import sys

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    N = int(next(it))
    M = 2 * N
    a = [[0] * (M + 1) for _ in range(M + 1)]
    for i in range(1, M):
        for j in range(i + 1, M + 1):
            a[i][j] = int(next(it))
    used = [False] * (M + 1)
    ans = 0

    def dfs(xor_val, cnt):
        nonlocal ans
        if cnt == N:
            if xor_val > ans:
                ans = xor_val
            return
        i = 1
        while i <= M and used[i]:
            i += 1
        used[i] = True
        for j in range(i + 1, M + 1):
            if not used[j]:
                used[j] = True
                dfs(xor_val ^ a[i][j], cnt + 1)
                used[j] = False
        used[i] = False

    dfs(0, 0)
    print(ans)

if __name__ == '__main__':
    main()

