using namespace std;
using ll = long long;

ll gcd(ll a, ll b) {
    while (b) { ll t = b; b = a % b; a = t; }
    return a;
}

ll f(ll X, ll N, ll M, ll L) {
    return X / N + X / M - 2 * (X / L);
}

int main() {
    ll N, M, K;
    if (!(cin >> N >> M >> K)) return 0;
    ll g = gcd(N, M);
    ll L = (N / g) * M; // lcm, safe because N,M <= 1e8
    ll lo = 1, hi = 9000000000000000000LL; // ~9e18, safe upper bound
    while (lo < hi) {
        ll mid = lo + (hi - lo) / 2;
        if (f(mid, N, M, L) >= K) {
            hi = mid;
        } else {
            lo = mid + 1;
        }
    }
    cout << lo << endl;
    return 0;
}

