import sys
from functools import lru_cache

def solve():
    data = sys.stdin.read().strip()
    if not data:
        return
    N = int(data)
    digits = tuple(int(c) for c in str(N))
    L = len(digits)
    max_S = L * 9
    ans = 0
    for S in range(1, max_S + 1):
        @lru_cache(maxsize=None)
        def dfs(idx, sum_so_far, rem, tight):
            if idx == L:
                return 1 if sum_so_far == S and rem == 0 else 0
            limit = digits[idx] if tight else 9
            total = 0
            for d in range(limit + 1):
                nsum = sum_so_far + d
                if nsum > S:
                    continue
                nrem = (rem * 10 + d) % S
                total += dfs(idx + 1, nsum, nrem, tight and d == limit)
            return total
        ans += dfs(0, 0, 0, True)
        dfs.cache_clear()
    print(ans)

if __name__ == '__main__':
    solve()

