const long long MOD = 998244353;
long long pow_mod(long long base, long long exp, long long mod) {
    long long res = 1 % mod;
    base %= mod;
    while (exp > 0) {
        if (exp & 1) res = (__int128)res * base % mod;
        base = (__int128)base * base % mod;
        exp >>= 1;
    }
    return res;
}
int main() {
    long long N;
    if (!(cin >> N)) return 0;
    int d = to_string(N).length();
    long long x = pow_mod(10, d, MOD);
    long long ans;
    if (x == 1) {
        ans = (N % MOD) * (N % MOD) % MOD;
    } else {
        long long xN = pow_mod(x, N, MOD);
        long long numerator = (xN - 1 + MOD) % MOD;
        long long inv_denom = pow_mod(x - 1, MOD - 2, MOD);
        long long sum = numerator * inv_denom % MOD;
        ans = (N % MOD) * sum % MOD;
    }
    cout << ans << endl;
    return 0;
}

