    char_to_idx = {'R': 0, 'P': 1, 'S': 2}
    INF = -10**9
    dp = [0, 0, 0]  # 第0局前，视为任意手势且胜场0
    for ch in S:
        a = char_to_idx[ch]
        new_dp = [INF, INF, INF]
        for c in range(3):
            # 合法：平局或获胜
            if c == a or (a + 1) % 3 == c:
                score = 1 if (a + 1) % 3 == c else 0
                max_prev = INF
                for prev in range(3):
                    if prev != c and dp[prev] > max_prev:
                        max_prev = dp[prev]
                if max_prev != INF:
                    new_dp[c] = score + max_prev
        dp = new_dp
    print(max(dp))

if __name__ == '__main__':
    main()

