#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;
using ll = long long;

struct Edge { int to; ll cost; };

vector<vector<Edge>> g;
ll total_sum = 0;
ll far_dist = 0;
int far_node = 0;

void dfs(int u, int p, ll d) {
    if (d > far_dist) { far_dist = d; far_node = u; }
    for (auto& e : g[u]) {
        if (e.to == p) continue;
        total_sum += e.cost;
        dfs(e.to, u, d + e.cost);
    }
}

void dfs2(int u, int p, ll d) {
    if (d > far_dist) far_dist = d;
    for (auto& e : g[u]) {
        if (e.to == p) continue;
        dfs2(e.to, u, d + e.cost);
    }
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int N; cin >> N;
    g.resize(N+1);
    for (int i=0; i<N-1; ++i) {
        int a,b; ll c; cin >> a >> b >> c;
        g[a].push_back({b,c});
        g[b].push_back({a,c});
    }
    total_sum = 0;
    far_dist = 0; far_node = 0;
    dfs(1, -1, 0);
    int u = far_node;
    far_dist = 0;
    dfs2(u, -1, 0);
    ll diam = far_dist;
    cout << 2 * total_sum - diam << "\n";
    return 0;
}

