using namespace std;
const int INF = 1e9;
int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int H, W, Y;
    cin >> H >> W >> Y;
    vector<vector<int>> A(H, vector<int>(W));
    for (int i=0;i<H;++i) for (int j=0;j<W;++j) cin >> A[i][j];
    vector<vector<int>> dist(H, vector<int>(W, INF));
    priority_queue<pair<int,pair<int,int>>, vector<pair<int,pair<int,int>>>, greater<>> pq;
    for (int i=0;i<H;++i) for (int j=0;j<W;++j)
        if (i==0||i==H-1||j==0||j==W-1) { dist[i][j]=A[i][j]; pq.push({A[i][j],{i,j}}); }
    int dir[4][2]={{1,0},{-1,0},{0,1},{0,-1}};
    while (!pq.empty()) {
        auto [d,p]=pq.top(); pq.pop();
        int i=p.first, j=p.second;
        if (d!=dist[i][j]) continue;
        for (int k=0;k<4;++k) {
            int ni=i+dir[k][0], nj=j+dir[k][1];
            if (ni<0||ni>=H||nj<0||nj>=W) continue;
            int nd=max(d, A[ni][nj]);
            if (nd<dist[ni][nj]) { dist[ni][nj]=nd; pq.push({nd,{ni,nj}}); }
        }
    }
    vector<int> cnt(Y+2,0);
    for (int i=0;i<H;++i) for (int j=0;j<W;++j) if (dist[i][j]<=Y) cnt[dist[i][j]]++;
    int rem=H*W;
    for (int y=1;y<=Y;++y) { rem-=cnt[y]; cout << rem << '\n'; }
    return 0;
}

