#include <iostream>
#include <vector>
using namespace std;

int main() {
    int N;
    if (!(cin >> N)) return 0;
    vector<int> A(N);
    for (int i = 0; i < N; ++i) cin >> A[i];
    long long ans = 0;
    for (int k = 0; k < 30; ++k) {
        int cnt0 = 1; // prefix_xor[0] = 0
        int cnt1 = 0;
        int bit_one_count = 0;
        int pref = 0;
        for (int i = 0; i < N; ++i) {
            int b = (A[i] >> k) & 1;
            pref ^= b;
            if (pref == 0) cnt0++;
            else cnt1++;
            if (b == 1) bit_one_count++;
        }
        long long contrib = (long long)cnt0 * cnt1 - bit_one_count;
        ans += contrib * (1LL << k);
    }
    cout << ans << endl;
    return 0;
}

