#include <bits/stdc++.h>
using namespace std;
struct DSU {
    vector<int> parent, sz;
    vector<vector<int>> top;
    DSU(int n) {
        parent.resize(n+1);
        sz.resize(n+1, 1);
        top.resize(n+1);
        for(int i=1;i<=n;i++) {
            parent[i]=i;
            top[i]={i};
        }
    }
    int find(int x) {
        if(parent[x]!=x) parent[x]=find(parent[x]);
        return parent[x];
    }
    void unite(int x, int y) {
        int rx=find(x), ry=find(y);
        if(rx==ry) return;
        if(sz[rx] < sz[ry]) swap(rx, ry);
        parent[ry]=rx;
        sz[rx]+=sz[ry];
        vector<int> nt;
        int i=0, j=0;
        while(nt.size()<10 && (i<top[rx].size() || j<top[ry].size())) {
            if(i<top[rx].size() && (j>=top[ry].size() || top[rx][i] > top[ry][j]))
                nt.push_back(top[rx][i++]);
            else
                nt.push_back(top[ry][j++]);
        }
        top[rx]=nt;
    }
    int query(int v, int k) {
        int rv=find(v);
        if(sz[rv] < k) return -1;
        return top[rv][k-1];
    }
};
int main() {
    ios::sync_with_stdio(false); cin.tie(0);
    int N,Q; cin>>N>>Q;
    DSU dsu(N);
    while(Q--) {
        int t; cin>>t;
        if(t==1) {
            int u,v; cin>>u>>v;
            dsu.unite(u,v);
        } else {
            int v,k; cin>>v>>k;
            cout<<dsu.query(v,k)<<'\n';
        }
    }
    return 0;

