import sys

def solve():
    data = sys.stdin.read().split()
    if not data:
        return
    N = int(data[0])
    groups = [[], [], []]
    S = 0
    idx = 1
    for _ in range(N):
        a = int(data[idx]); b = int(data[idx+1]); idx += 2
        groups[a-1].append(b)
        S += b
    if S % 3 != 0:
        print(-1)
        return
    T = S // 3
    INF = 10**9
    dp = [[INF]*(T+1) for _ in range(T+1)]
    dp[0][0] = 0
    prev_sum = 0
    for team in range(3):
        for b in groups[team]:
            new_dp = [[INF]*(T+1) for _ in range(T+1)]
            for s1 in range(T+1):
                for s2 in range(T+1):
                    if dp[s1][s2] == INF:
                        continue
                    s3 = prev_sum - s1 - s2
                    if s3 < 0 or s3 > T:
                        continue
                    for dest in range(3):
                        ns1 = s1 + (b if dest == 0 else 0)
                        ns2 = s2 + (b if dest == 1 else 0)
                        ns3 = s3 + (b if dest == 2 else 0)
                        if ns1 <= T and ns2 <= T and ns3 <= T:
                            cost = dp[s1][s2] + (0 if dest == team else 1)
                            if cost < new_dp[ns1][ns2]:
                                new_dp[ns1][ns2] = cost
            dp = new_dp
            prev_sum += b
    ans = dp[T][T]
    print(-1 if ans == INF else ans)

if __name__ == '__main__':
    solve()

