using namespace std;
using ll = long long;
int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int N, M;
    ll Sx, Sy;
    if (!(cin >> N >> M >> Sx >> Sy)) return 0;
    map<ll, set<ll>> horiz;
    map<ll, set<ll>> vert;
    for (int i = 0; i < N; ++i) {
        ll X, Y;
        cin >> X >> Y;
        horiz[Y].insert(X);
        vert[X].insert(Y);
    }
    ll cur_x = Sx, cur_y = Sy, ans_c = 0;
    for (int i = 0; i < M; ++i) {
        char D; ll C;
        cin >> D >> C;
        ll nx = cur_x, ny = cur_y;
        if (D == 'U') ny += C;
        else if (D == 'D') ny -= C;
        else if (D == 'L') nx -= C;
        else if (D == 'R') nx += C;
        if (D == 'U' || D == 'D') {
            ll x = cur_x, y1 = min(cur_y, ny), y2 = max(cur_y, ny);
            auto& s = vert[x];
            auto it = s.lower_bound(y1);
            while (it != s.end() && *it <= y2) {
                ans_c++; ll y = *it;
                horiz[y].erase(x);
                it = s.erase(it);
            }
        } else {
            ll y = cur_y, x1 = min(cur_x, nx), x2 = max(cur_x, nx);
            auto& s = horiz[y];
            auto it = s.lower_bound(x1);
            while (it != s.end() && *it <= x2) {
                ans_c++; ll x = *it;
                vert[x].erase(y);
                it = s.erase(it);
            }
        }
        cur_x = nx; cur_y = ny;
    }
    cout << cur_x << " " << cur_y << " " << ans_c << "\n";
    return 0;
}

