#include <iostream>
#include <vector>
using namespace std;

struct Fenwick {
    int n;
    vector<long long> bit;
    Fenwick(int n): n(n), bit(n+1, 0) {}
    void add(int i, long long v) {
        for (; i <= n; i += i & -i) bit[i] += v;
    }
    long long sum(int i) {
        long long s = 0;
        for (; i > 0; i -= i & -i) s += bit[i];
        return s;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int N, M;
    if (!(cin >> N >> M)) return 0;
    Fenwick fc(M), fs(M);
    fc.add(1, 1); // S[0] = 0 at index 1
    fs.add(1, 0);
    long long ans = 0;
    long long cur = 0;
    for (int r = 1; r <= N; ++r) {
        long long a; cin >> a;
        cur = (cur + a) % M;
        int idx = (int)cur + 1;
        long long cnt_le = fc.sum(idx);
        long long sum_le = fs.sum(idx);
        long long cnt_total = r; // previous prefixes count = r (S[0]..S[r-1])
        long long sum_total = fs.sum(M);
        long long contrib = cnt_total * cur - sum_total + (long long)M * (cnt_total - cnt_le);
        ans += contrib;
        fc.add(idx, 1);
        fs.add(idx, cur);
    }
    cout << ans << '\n';
    return 0;
}

