#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
struct Edge { int u, v, w; bool operator<(const Edge& o) const { return w < o.w; } };
const int MAXN = 400005;
int N, M, K;
int parent[MAXN], a[MAXN], b[MAXN];
ll w[MAXN];
vector<int> children[MAXN];
ll ans = 0;

int find(int x) { return parent[x] == x ? x : parent[x] = find(parent[x]); }

int dfs(int u) {
    ll Splus = (u <= N ? a[u] : 0);
    ll Sminus = (u <= N ? b[u] : 0);
    for (int v : children[u]) {
        int d = dfs(v);
        if (d > 0) Splus += d;
        else Sminus -= d;
    }
    ans += min(Splus, Sminus) * w[u];
    return (int)(Splus - Sminus);
}

int main() {
    scanf("%d%d%d", &N, &M, &K);
    vector<Edge> edges(M);
    for (int i = 0; i < M; i++) scanf("%d%d%d", &edges[i].u, &edges[i].v, &edges[i].w);
    sort(edges.begin(), edges.end());
    for (int i = 1; i <= 2 * N; i++) parent[i] = i;
    int node = N;
    for (auto& e : edges) {
        int ru = find(e.u), rv = find(e.v);
        if (ru != rv) {
            int nd = ++node;
            w[nd] = e.w;
            children[nd].push_back(ru);
            children[nd].push_back(rv);
            parent[ru] = nd; parent[rv] = nd;
        }
    }
    for (int i = 0; i < K; i++) { int x; scanf("%d", &x); a[x]++; }
    for (int i = 0; i < K; i++) { int x; scanf("%d", &x); b[x]++; }
    int root = find(1);
    dfs(root);
    printf("%lld\n", ans);
    return 0;
}

