#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;
using ll = long long;

int N;
ll M;
vector<ll> P;

ll count_at(ll C) {
    __int128 sum = 0;
    for (int i = 0; i < N; ++i) {
        ll k = (C + P[i]) / (2 * P[i]);
        sum += k;
        if (sum > (__int128)1e18) return 1e18;
    }
    return (ll)sum;
}

bool check(ll S) {
    if (S == 0) return true;
    ll lo = 1, hi = 4e18;
    while (lo < hi) {
        ll mid = lo + (hi - lo) / 2;
        if (count_at(mid) >= S) hi = mid;
        else lo = mid + 1;
    }
    ll C = lo;
    __int128 base = 0;
    vector<ll> marg;
    for (int i = 0; i < N; ++i) {
        ll k = (C + P[i]) / (2 * P[i]);
        if (k > 0) {
            base += (__int128)P[i] * k * k;
            marg.push_back((2 * k - 1) * P[i]);
        }
    }
    ll T = count_at(C);
    ll R = T - S;
    if (R > 0) {
        sort(marg.rbegin(), marg.rend());
        for (ll i = 0; i < R; ++i) base -= marg[i];
    }
    return base <= (__int128)M;
}

int main() {
    cin >> N >> M;
    P.resize(N);
    for (int i = 0; i < N; ++i) cin >> P[i];
    ll lo = 0, hi = 1000000000000LL;
    while (lo < hi) {
        ll mid = lo + (hi - lo + 1) / 2;
        if (check(mid)) lo = mid;
        else hi = mid - 1;
    }
    cout << lo << endl;
    return 0;
}

